-- Wanna Go · SEO 2026-11: guía y preguntas frecuentes en los destinos, y etiqueta del inicio.
-- Aplicar en Supabase (SQL Editor) ANTES de unir la rama a main: la acción baja el contenido de la base
-- y reescribe contenido/; sin esto, la guía, las preguntas y la etiqueta nueva no salen en el sitio.
-- TODO-DATO: precios, punto de encuentro y horarios siguen pendientes (ver notas <!-- --> en cada guía).

alter table public.destinos add column if not exists guia public.bilingue not null default '{"es": "", "en": ""}';
alter table public.destinos add column if not exists faq jsonb not null default '[]' check (jsonb_typeof(faq) = 'array');
comment on column public.destinos.guia is 'Guía larga opcional (formato del blog: ### subtítulo, - lista, 1. pasos). Las líneas <!-- --> no se publican.';
comment on column public.destinos.faq is 'Preguntas frecuentes [{pregunta, respuesta}] bilingües. Salen en la página y como FAQPage para Google.';

update public.destinos set
  guia = $wg${"es": "### Historia y transformación\n\nLa Comuna 13, en el occidente de Medellín, sobre las laderas del barrio San Javier, vivió durante años el conflicto armado urbano. La Operación Orión, en 2002, marcó uno de los momentos más duros de su historia. Lo que vino después es lo que hoy atrae a viajeros de todo el mundo: un barrio que decidió contar su propia historia con arte, música y organización comunitaria.\n\nLa llegada del Metrocable y, en 2011, de las escaleras eléctricas al aire libre conectaron a los vecinos de la parte alta con el resto de la ciudad. Alrededor de ellas nacieron el grafitour, los colectivos de hip hop y decenas de negocios familiares que viven del turismo.\n\n### Qué verás en el recorrido\n\n- **Grafitis con significado:** murales sobre la memoria, la resistencia y la esperanza, pintados por artistas del barrio. Cada uno tiene una historia que tus guías conocen de primera mano.\n- **Las escaleras eléctricas:** varios tramos al aire libre que suben la ladera y cambiaron la vida diaria de quienes antes subían cientos de escalones a pie.\n- **Miradores sobre Medellín:** desde la parte alta se ve buena parte del valle de Aburrá.\n- **Hip hop y baile en la calle:** grupos del barrio que convirtieron la música en una forma de transformar su entorno.\n- **Sabores locales:** paletas artesanales, empanadas y café en negocios de familias del barrio.\n\n### Itinerario del tour\n\n<!-- TODO-DATO: confirmar con Luchy punto de encuentro, hora de salida y si incluye transporte desde el hotel -->\n\n1. Encuentro en Medellín y traslado hacia San Javier.\n2. Llegada al barrio y contexto histórico con un guía local.\n3. Grafitour a pie por los murales principales.\n4. Subida por las escaleras eléctricas y parada en los miradores.\n5. Tiempo para música, baile y compras en tiendas de artistas.\n6. Pausa para probar los sabores del barrio y regreso.\n\n### Duración\n\nEl recorrido toma medio día. Lo ajustamos a tu ritmo y podemos combinarlo en el mismo día con otros planes en Medellín, como las plazas de mercado.\n\n<!-- TODO-DATO: precio por persona y tamaño de grupo; no publicar hasta que Luchy los confirme -->\n\n### Qué llevar\n\n- Zapatos cómodos: hay calles empinadas y escalones.\n- Protector solar, gorra e hidratación.\n- Una chaqueta ligera por si llueve.\n- Efectivo en billetes pequeños para comprar arte, paletas o dejar una propina a los artistas.\n- Cámara o celular con batería: es uno de los barrios más fotogénicos de la ciudad.\n\n### Seguridad\n\nLa zona turística de la Comuna 13 recibe visitantes todos los días y recorrerla con guías del barrio es la mejor forma de vivirla con tranquilidad. Te recomendamos no salir de la ruta del recorrido, cuidar tus pertenencias como en cualquier ciudad grande y pedir permiso antes de fotografiar a las personas.\n\n### Cómo llegar\n\nLa Comuna 13 queda en el occidente de Medellín. En metro, la forma más sencilla es llegar a la estación San Javier y desde allí seguir hacia el barrio. Si viajas con Wanna Go, coordinamos el traslado para que no tengas que preocuparte por la logística.", "en": ""}$wg$::jsonb,
  faq = $wg$[{"pregunta": {"es": "¿Es seguro visitar la Comuna 13?", "en": ""}, "respuesta": {"es": "La zona turística recibe visitantes todos los días. Recorrerla con guías que nacieron en el barrio, sin salir de la ruta y cuidando tus pertenencias como en cualquier ciudad grande, es la mejor forma de visitarla con tranquilidad.", "en": ""}}, {"pregunta": {"es": "¿Cuánto dura el tour por la Comuna 13?", "en": ""}, "respuesta": {"es": "Planea medio día. Podemos ajustarlo a tu ritmo o combinarlo con otros planes en Medellín el mismo día.", "en": ""}}, {"pregunta": {"es": "¿Cómo llego a la Comuna 13?", "en": ""}, "respuesta": {"es": "En metro, hasta la estación San Javier, y desde allí hacia el barrio. Si viajas con Wanna Go, coordinamos el traslado por ti.", "en": ""}}, {"pregunta": {"es": "¿Qué debo llevar al tour?", "en": ""}, "respuesta": {"es": "Zapatos cómodos, protector solar, agua, una chaqueta ligera por si llueve y efectivo en billetes pequeños para comprar arte o comida en los negocios locales.", "en": ""}}, {"pregunta": {"es": "¿Puedo hacer el tour en grupo o en privado?", "en": ""}, "respuesta": {"es": "Sí. Diseñamos el recorrido para viajeros que van solos, parejas, familias y grupos. Escríbenos por WhatsApp y armamos la experiencia a tu medida.", "en": ""}}]$wg$::jsonb
where url = 'comuna-13';

update public.destinos set
  guia = $wg${"es": "### Qué hacer en Guatapé\n\n- **Subir la Piedra del Peñol:** más de 700 escalones hasta la cima, con una de las vistas más amplias de Antioquia sobre el embalse y sus islas.\n- **Recorrer los zócalos:** las fachadas del pueblo tienen relieves de colores que muestran oficios, animales y escenas de la vida local. Vale la pena caminarlas sin prisa.\n- **Navegar el embalse:** un paseo en lancha entre islas y montañas para ver el paisaje desde el agua.\n- **Probar la cocina local:** un almuerzo frente al embalse o en la plaza del pueblo.\n\n### Itinerario sugerido\n\n<!-- TODO-DATO: confirmar hora de salida desde Medellín, si incluye almuerzo y la entrada a la Piedra -->\n\n1. Salida temprano desde Medellín por carretera, unas dos horas de viaje.\n2. Subida a la Piedra del Peñol antes de que llegue la mayor cantidad de visitantes.\n3. Almuerzo y recorrido a pie por las calles de zócalos.\n4. Paseo por el embalse y regreso a Medellín, o noche en Guatapé si eliges el plan de dos días.\n\n### Duración\n\nSe puede hacer en un día desde Medellín, pero con dos días lo vives con más calma: amaneceres sobre el embalse, el pueblo sin multitudes y tiempo para descansar.\n\n<!-- TODO-DATO: precio por persona para 1 y 2 días; no publicar hasta que Luchy lo confirme -->\n\n### Qué llevar\n\n- Zapatos cómodos para los escalones de la Piedra.\n- Protector solar, gorra y agua.\n- Una chaqueta ligera para la lancha o la tarde.\n- Efectivo para artesanías y pequeños gastos en el pueblo.", "en": ""}$wg$::jsonb,
  faq = $wg$[{"pregunta": {"es": "¿Cuántos escalones tiene la Piedra del Peñol?", "en": ""}, "respuesta": {"es": "Más de 700. La subida se hace a tu ritmo y hay puntos para descansar en el camino.", "en": ""}}, {"pregunta": {"es": "¿Cuánto se tarda de Medellín a Guatapé?", "en": ""}, "respuesta": {"es": "Unas dos horas por carretera desde Medellín.", "en": ""}}, {"pregunta": {"es": "¿Guatapé se puede visitar en un día?", "en": ""}, "respuesta": {"es": "Sí, es un plan de un día muy popular. Si quieres vivirlo con más calma, te recomendamos quedarte una noche.", "en": ""}}, {"pregunta": {"es": "¿Cuál es la mejor época para ir a Guatapé?", "en": ""}, "respuesta": {"es": "Se puede visitar todo el año. Para evitar multitudes, conviene ir entre semana o subir a la Piedra temprano.", "en": ""}}, {"pregunta": {"es": "¿Con quién puedo ir a Guatapé con Wanna Go?", "en": ""}, "respuesta": {"es": "Diseñamos el viaje para familias, parejas y grupos, con transporte y planes a tu medida. Escríbenos por WhatsApp para armarlo.", "en": ""}}]$wg$::jsonb
where url = 'guatape';

update public.paginas set contenido = jsonb_set(contenido, '{portada,etiqueta}', $wg${"en": "Travel agency in Medellín · Inbound tourism", "es": "Agencia de viajes en Medellín · Turismo receptivo"}$wg$::jsonb)
where id = 'inicio';
